CREATE DATABASE IF NOT EXISTS univault_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE univault_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS activity_logs, downloads, bookmarks, resources, modules, subjects, semesters, courses, departments, users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL UNIQUE,short_name VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY,department_id INT NOT NULL,name VARCHAR(160) NOT NULL,level VARCHAR(50) DEFAULT 'Postgraduate',UNIQUE KEY uq_course(department_id,name),FOREIGN KEY(department_id) REFERENCES departments(id)) ENGINE=InnoDB;
CREATE TABLE semesters(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,sort_order INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE subjects(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,semester_id INT NOT NULL,code VARCHAR(30) NOT NULL,name VARCHAR(180) NOT NULL,academic_year VARCHAR(20),UNIQUE KEY uq_subject(course_id,semester_id,code),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(semester_id) REFERENCES semesters(id)) ENGINE=InnoDB;
CREATE TABLE modules(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT NOT NULL,module_no INT NOT NULL,title VARCHAR(180) NOT NULL,topics TEXT,UNIQUE KEY uq_module(subject_id,module_no),FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','faculty','admin') NOT NULL DEFAULT 'student',department_id INT NULL,status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE resources(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,type ENUM('question_paper','syllabus','notes','assignment','presentation','other') NOT NULL,department_id INT NULL,course_id INT NULL,semester_id INT NULL,subject_id INT NULL,module_id INT NULL,exam_year SMALLINT NULL,exam_type VARCHAR(40) NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(100) NOT NULL UNIQUE,mime_type VARCHAR(120) NOT NULL,file_size BIGINT NOT NULL,uploaded_by INT NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',reviewed_by INT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_resources_status(status),INDEX idx_resources_subject(subject_id),INDEX idx_resources_type(type),FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(module_id) REFERENCES modules(id) ON DELETE SET NULL,FOREIGN KEY(uploaded_by) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE bookmarks(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,resource_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bookmark(user_id,resource_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE downloads(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,resource_id INT NOT NULL,downloaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,action VARCHAR(80) NOT NULL,resource_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE SET NULL) ENGINE=InnoDB;
